### Structure for Student Marks and Grade-1 Filter

```c
#include <stdio.h>

#define NUM_SUBJECTS 3
#define NUM_STUDENTS 4

// Structure definition
struct Student {
    char name[50];
    float marks[NUM_SUBJECTS];
    char grade;
};

int main() {
    struct Student students[NUM_STUDENTS] = {
        {"Rahul", {85.0, 90.0, 88.0}, ' '},
        {"Anjali", {72.0, 68.0, 75.0}, ' '},
        {"Vikram", {92.0, 95.0, 89.0}, ' '},
        {"Priya", {60.0, 65.0, 70.0}, ' '}
    };

    printf("Students securing Grade-1 (Average marks between 80 and 100):\n");
    printf("%-15s %-15s %-10s\n", "Name", "Average Marks", "Grade");
    printf("------------------------------------------\n");

    for (int i = 0; i < NUM_STUDENTS; i++) {
        float total = 0;
        for (int j = 0; j < NUM_SUBJECTS; j++) {
            total += students[i].marks[j];
        }
        float avg = total / NUM_SUBJECTS;

        // Grade-1 range: 80-100
        if (avg >= 80.0 && avg <= 100.0) {
            students[i].grade = '1';
            printf("%-15s %-15.2f %-10c\n", students[i].name, avg, students[i].grade);
        } else {
            students[i].grade = '2';
        }
    }

    return 0;
}

```

**Output:**

```text
Students securing Grade-1 (Average marks between 80 and 100):
Name            Average Marks   Grade     
------------------------------------------
Rahul           87.67           1         
Vikram          92.00           1
```

### Memory Allocation Snippet for Matrix Multiplication ($A \times B$)

For matrix multiplication $C = A \times B$, let matrix $A$ have dimensions $r_1 \times c_1$ and matrix $B$ have dimensions $r_2 \times c_2$. Multiplication is valid only if $c_1 = r_2$. The product matrix $C$ has dimensions $r_1 \times c_2$.

```c
#include <stdio.h>
#include <stdlib.h>

void allocateMatrixMultiplication(int r1, int c1, int r2, int c2) {
    if (c1 != r2) {
        printf("Multiplication not possible: Columns of A (%d) != Rows of B (%d)\n", c1, r2);
        return;
    }

    // 1. Allocate Matrix A (r1 x c1)
    int **A = (int **)malloc(r1 * sizeof(int *));
    for (int i = 0; i < r1; i++) {
        A[i] = (int *)malloc(c1 * sizeof(int));
    }

    // 2. Allocate Matrix B (r2 x c2)
    int **B = (int **)malloc(r2 * sizeof(int *));
    for (int i = 0; i < r2; i++) {
        B[i] = (int *)malloc(c2 * sizeof(int));
    }

    // 3. Allocate Result Matrix C (r1 x c2)
    int **C = (int **)malloc(r1 * sizeof(int *));
    for (int i = 0; i < r1; i++) {
        C[i] = (int *)calloc(c2, sizeof(int)); // calloc zeroes out initial sum
    }

    printf("Successfully allocated memory for Matrix A (%dx%d), B (%dx%d), and C (%dx%d).\n", 
           r1, c1, r2, c2, r1, c2);

    // Proper Deallocation to prevent memory leaks
    for (int i = 0; i < r1; i++) free(A[i]);
    free(A);

    for (int i = 0; i < r2; i++) free(B[i]);
    free(B);

    for (int i = 0; i < r1; i++) free(C[i]);
    free(C);
}

```

**Key Points:**
- We allocate an array of pointer-to-pointers (`int**`), followed by row allocations.
- Using `calloc` for the result matrix $C$ ensures all elements start initialized to 0, which is ideal for accumulating products ($C_{i,j} += A_{i,k} \times B_{k,j}$).

### Convenient Data Structure: Circular Linked List

**Why Circular Linked List?**
In an Operating System, the Round-Robin CPU scheduler allocates a time quantum to each running process. When a process finishes its time slice, the CPU immediately preempts it and moves to the next process.
- In a **linear linked list**, reaching the last node yields `NULL`, requiring a pointer reset back to `head`.
- In a **Circular Linked List (CLL)**, the last node's `next` pointer directly references the `head` node (`last->next = head`), providing seamless $O(1)$ continuous cycling without special edge conditions.

```c
#include <stdio.h>
#include <stdlib.h>

// Process Control Block (PCB) represented as a Circular Linked List node
struct ProcessNode {
    int pid;             // Process ID
    int burstTime;       // Remaining execution time
    struct ProcessNode* next;
};

// Insert new process at the end of the circular list
struct ProcessNode* addProcess(struct ProcessNode* head, int pid, int burstTime) {
    struct ProcessNode* newNode = (struct ProcessNode*)malloc(sizeof(struct ProcessNode));
    newNode->pid = pid;
    newNode->burstTime = burstTime;

    if (head == NULL) {
        newNode->next = newNode;
        return newNode;
    }

    struct ProcessNode* curr = head;
    while (curr->next != head) {
        curr = curr->next;
    }
    curr->next = newNode;
    newNode->next = head;
    return head;
}

// Simulate Round Robin CPU cycling
void roundRobinCycle(struct ProcessNode* head, int timeQuantum, int rounds) {
    if (head == NULL) return;
    struct ProcessNode* curr = head;

    printf("Simulating CPU Round-Robin Cycling (Quantum = %d ms):\n", timeQuantum);
    for (int step = 1; step <= rounds; step++) {
        printf("Step %d: Executing Process P%d (Remaining: %d ms)\n", 
               step, curr->pid, curr->burstTime);
        curr->burstTime -= timeQuantum;
        if (curr->burstTime < 0) curr->burstTime = 0;
        curr = curr->next; // Cycles naturally around to front
    }
}
```

### Suitable Data Structure: Circular Singly Linked List

**Justification:**
The **Josephus Problem** involves $n$ people standing in a circle where every $k$-th person is counted and eliminated until only one survivor remains.
A **Circular Singly Linked List (CSLL)** is ideal because:
1. The circular arrangement reflects the circular geometry naturally without index modulo arithmetic.
2. Once the $(k-1)$-th node is reached, unlinking the $k$-th node takes $O(1)$ pointer operations.

#### Demonstration ($n = 5$ people, eliminate every $k = 2$-nd person):
- **Circle:** `1 -> 2 -> 3 -> 4 -> 5 -> (loops to 1)`
- **Round 1:** Start at 1, count 2 $\to$ Eliminate **2**. List: `1 -> 3 -> 4 -> 5 -> (loops to 1)`
- **Round 2:** Start at 3, count 2 $\to$ Eliminate **4**. List: `1 -> 3 -> 5 -> (loops to 1)`
- **Round 3:** Start at 5, count 2 $\to$ Eliminate **1**. List: `3 -> 5 -> (loops to 3)`
- **Round 4:** Start at 3, count 2 $\to$ Eliminate **5**. List: `3`
- **Survivor:** **Person 3**.

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

int josephus(int n, int k) {
    // Create circular linked list with n nodes
    struct Node *head = (struct Node*)malloc(sizeof(struct Node));
    head->data = 1;
    struct Node *prev = head;
    for (int i = 2; i <= n; i++) {
        struct Node *temp = (struct Node*)malloc(sizeof(struct Node));
        temp->data = i;
        prev->next = temp;
        prev = temp;
    }
    prev->next = head; // Make circular

    // Elimination loop
    struct Node *ptr1 = head, *ptr2 = head;
    while (ptr1->next != ptr1) {
        // Count k-1 nodes to find the node preceding the k-th node
        for (int i = 0; i < k - 1; i++) {
            ptr2 = ptr1;
            ptr1 = ptr1->next;
        }
        // Delete the k-th node (ptr1)
        printf("Eliminated person: %d\n", ptr1->data);
        ptr2->next = ptr1->next;
        free(ptr1);
        ptr1 = ptr2->next;
    }
    int survivor = ptr1->data;
    free(ptr1);
    return survivor;
}
```

### Finding Maximum and Minimum in an Array using Dynamic Memory Allocation

#### 1. Pseudocode:

```text
Algorithm FindMinMaxDynamic(n):
    Input: Integer n (size of array)
    Output: Maximum and Minimum values in the array

    Step 1: If n <= 0 then
                Print "Invalid array size"
                Exit
            End If

    Step 2: Allocate memory dynamically on Heap for n integers
            arr = AllocateMemory(n * sizeof(Integer))
            If arr == NULL then
                Print "Memory allocation failed"
                Exit
            End If

    Step 3: Read n elements into arr[0 ... n-1]

    Step 4: Initialize min = arr[0], max = arr[0]

    Step 5: For i = 1 to n - 1 do
                If arr[i] > max then
                    max = arr[i]
                End If
                If arr[i] < min then
                    min = arr[i]
                End If
            End For

    Step 6: Print "Maximum value = ", max
            Print "Minimum value = ", min

    Step 7: Deallocate dynamically allocated memory
            Free(arr)

```

#### 2. C Program Implementation:

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    printf("Enter the number of elements: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid array size.\n");
        return 1;
    }

    // Dynamic Memory Allocation using malloc
    int *arr = (int *)malloc(n * sizeof(int));
    if (arr == NULL) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Finding Min and Max
    int min = arr[0];
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) max = arr[i];
        if (arr[i] < min) min = arr[i];
    }

    printf("\n--- Results ---\n");
    printf("Maximum Element = %d\n", max);
    printf("Minimum Element = %d\n", min);

    // Release dynamic memory to prevent memory leak
    free(arr);
    arr = NULL;

    return 0;
}

```

**Complexity Analysis:**
- **Time Complexity:** $O(n)$ — Single linear scan with $2(n - 1)$ comparisons.
- **Space Complexity:** $O(n)$ on the heap for dynamically allocated array.

### Circular Singly Linked List (CSLL) Sorted Insertion and Deletion

#### 1. Analysis of Operations:
- **Initial sorted CSLL:** `[10] -> [25] -> [42] -> [55] -> [61] -> (wraps back to [10])`
- **Operation 1 (Insert 50):**
  - Scan from `10`: $10 < 50, 25 < 50, 42 < 50, 55 > 50$.
  - The right place to insert `50` is **between 42 and 55**.
  - Relink: `node(42)->next = newNode(50)`, `newNode(50)->next = node(55)`.
- **Operation 2 (Delete 61):**
  - Node `61` is the last node, preceded by `55`.
  - Relink: `node(55)->next = node(61)->next` (which is `node(10)`).
  - Free `node(61)`.

#### 2. Pictorial Representations:

**Initial State:**

```text
Head ──► [ 10 ] ──► [ 25 ] ──► [ 42 ] ──► [ 55 ] ──► [ 61 ] ──┐
          ▲                                                    │
          └────────────────────────────────────────────────────┘

```

**After Inserting 50 (Between 42 and 55):**

```text
Head ──► [ 10 ] ──► [ 25 ] ──► [ 42 ] ──► [ 50 ] ──► [ 55 ] ──► [ 61 ] ──┐
          ▲                                                              │
          └──────────────────────────────────────────────────────────────┘

```

**After Deleting 61 (Final List):**

```text
Head ──► [ 10 ] ──► [ 25 ] ──► [ 42 ] ──► [ 50 ] ──► [ 55 ] ──┐
          ▲                                                    │
          └────────────────────────────────────────────────────┘

```

#### 3. C Implementation:

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

struct Node* insertSorted(struct Node* head, int val) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = val;

    if (head == NULL) {
        newNode->next = newNode;
        return newNode;
    }

    // Case: Insert before head
    if (val < head->data) {
        struct Node* last = head;
        while (last->next != head) last = last->next;
        last->next = newNode;
        newNode->next = head;
        return newNode;
    }

    // Traverse to locate proper insertion point
    struct Node* curr = head;
    while (curr->next != head && curr->next->data < val) {
        curr = curr->next;
    }
    newNode->next = curr->next;
    curr->next = newNode;
    return head;
}

struct Node* deleteNode(struct Node* head, int key) {
    if (head == NULL) return NULL;

    struct Node *curr = head, *prev = NULL;
    // Find the node
    while (curr->data != key) {
        if (curr->next == head) return head; // Not found
        prev = curr;
        curr = curr->next;
    }

    // If node to delete is only node
    if (curr->next == head && prev == NULL) {
        free(curr);
        return NULL;
    }

    // Deleting non-head node
    prev->next = curr->next;
    free(curr);
    return head;
}

void display(struct Node* head) {
    if (head == NULL) return;
    struct Node* temp = head;
    do {
        printf("%d -> ", temp->data);
        temp = temp->next;
    } while (temp != head);
    printf("(back to %d)\n", head->data);
}

int main() {
    struct Node* head = NULL;
    int initial[] = {10, 25, 42, 55, 61};
    for (int i = 0; i < 5; i++) head = insertSorted(head, initial[i]);

    printf("Initial list: ");
    display(head);

    // Step 1: Add 50 in sorted position
    head = insertSorted(head, 50);
    printf("After adding 50: ");
    display(head);

    // Step 2: Delete 61
    head = deleteNode(head, 61);
    printf("After deleting 61: ");
    display(head);

    return 0;
}
```

### Doubly Linked List (DLL) Modification

#### 1. Initial State:
`NULL ◄── [Item AA] ⇄ [Item BB] ⇄ [Item CC] ⇄ [Item DD] ⇄ [Item EE] ⇄ [Item FF] ──► NULL`

#### 2. Operations:
- **Operation 1 (Remove `Item AA`):**  
  `Item AA` is the head of the list. We update `Head = Head->next` (`Item BB`), set `Head->prev = NULL`, and free the old head node.
  - *Intermediate List:* `NULL ◄── [Item BB] ⇄ [Item CC] ⇄ [Item DD] ⇄ [Item EE] ⇄ [Item FF] ──► NULL`

- **Operation 2 (Insert `Item GG` after `Item DD`):**  
  Traverse to node `Item DD`. Create a new node containing `Item GG`.
  - `new_node->next = dd_node->next` (`Item EE`)
  - `new_node->prev = dd_node` (`Item DD`)
  - `dd_node->next->prev = new_node`
  - `dd_node->next = new_node`

#### 3. Final State:
`NULL ◄── [Item BB] ⇄ [Item CC] ⇄ [Item DD] ⇄ [Item GG] ⇄ [Item EE] ⇄ [Item FF] ──► NULL`

#### 4. C Program Implementation:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node {
    char item[20];
    struct Node* prev;
    struct Node* next;
};

struct Node* append(struct Node* head, const char* val) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    strcpy(newNode->item, val);
    newNode->next = NULL;
    newNode->prev = NULL;

    if (head == NULL) return newNode;

    struct Node* temp = head;
    while (temp->next != NULL) temp = temp->next;
    temp->next = newNode;
    newNode->prev = temp;
    return head;
}

struct Node* removeHead(struct Node* head) {
    if (head == NULL) return NULL;
    struct Node* temp = head;
    head = head->next;
    if (head != NULL) {
        head->prev = NULL;
    }
    free(temp);
    return head;
}

void insertAfter(struct Node* head, const char* target, const char* newVal) {
    struct Node* curr = head;
    while (curr != NULL && strcmp(curr->item, target) != 0) {
        curr = curr->next;
    }
    if (curr == NULL) return;

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    strcpy(newNode->item, newVal);
    newNode->next = curr->next;
    newNode->prev = curr;
    if (curr->next != NULL) {
        curr->next->prev = newNode;
    }
    curr->next = newNode;
}

void printList(struct Node* head) {
    struct Node* temp = head;
    printf("NULL <-> ");
    while (temp != NULL) {
        printf("[%s] <-> ", temp->item);
        temp = temp->next;
    }
    printf("NULL\n");
}

int main() {
    struct Node* list = NULL;
    list = append(list, "Item AA");
    list = append(list, "Item BB");
    list = append(list, "Item CC");
    list = append(list, "Item DD");
    list = append(list, "Item EE");
    list = append(list, "Item FF");

    printf("Initial List:\n");
    printList(list);

    // 1. Remove Item AA
    list = removeHead(list);
    printf("\nAfter removing Item AA:\n");
    printList(list);

    // 2. Insert Item GG after Item DD
    insertAfter(list, "Item DD", "Item GG");
    printf("\nFinal List after inserting Item GG after Item DD:\n");
    printList(list);

    return 0;
}
```
